begin;
with s(name,type,description,vibe,hours,link,location,lat,lng,intel) as (values
('Relokant Bar','bar','Yerevan''s clearest current queer nightlife address is small, social and defiantly alive. Relokant runs LGBTQ+ parties, karaoke and community nights that gather force late, making it the best first connection to the local scene rather than a polished destination club.','late-blooming queer room where karaoke, parties and chosen family take over','Programme-led; current guides report the room becomes lively after 23:00. Confirm the same-day event and entrance details before going.','https://www.instagram.com/relokant.yerevan/','Yerevan, Armenia — confirm the current entrance directly with the venue',40.1811,44.5136,'{"queue_wait":"The room is intimate and event-led; a popular karaoke or party can fill it after 23:00. Confirm the entrance and any door contribution directly before travelling.","best_nights":"Choose a same-week LGBTQ+ party, karaoke or community announcement. An ordinary open night can be conversational; the advertised programme creates the stronger queer crowd.","crowd_mix":"Queer Armenians, relocants, activists, artists and trusted international visitors form a small room where social connection matters as much as the music.","dress_code":"Personal, casual and expressive looks fit. Keep photography consent-based because visibility can carry consequences for local guests.","staff_inclusivity":"Relokant publicly centres queer parties and is identified by a current 2026 guide as Yerevan''s main queer venue. That is direct programme evidence; verify the current host and entry details because the scene changes quickly.","source_urls":["https://www.instagram.com/relokant.yerevan/","https://www.gayout.com/europe/armenia/yerevan"],"research_status":"editorial_review_consensus","updated_at":"2026-08-29T00:00:00Z"}'::jsonb),
('Esthetic Joys Embassy','bar','Part listening room, part art-world living room, Esthetic Joys Embassy draws a mixed creative crowd near the Cascade. Jazz, vinyl and occasional queer programming give it relevance without turning a culturally open bar into a permanently dedicated LGBTQ+ venue.','bohemian Sarmen Street salon for jazz, selectors and beautiful misfits','Evening and event-led; verify the current programme and opening time on the venue''s social channel.','https://www.instagram.com/esthetic.joys.embassy/','72 Sarmen Street, Yerevan, Armenia',40.1906,44.5135,'{"queue_wait":"Small concerts and selector nights can compress the Sarmen Street room. Check the programme and arrive early when a seated jazz set matters.","best_nights":"Follow the venue for a named jazz, vinyl or queer-associated programme; on unprogrammed nights expect a mixed creative bar rather than a dedicated LGBTQ+ gathering.","crowd_mix":"Musicians, designers, art workers, younger locals, visiting creatives and queer friend groups mix in a bohemian Cascade-side setting.","dress_code":"Art-scene casual works better than formal nightlife polish. Respect performers and ask before photographing people in the room.","staff_inclusivity":"Current queer travel coverage identifies occasional queer events and a welcoming mixed crowd. The venue does not publish a permanent LGBTQ+ safe-space policy, so programme-specific evidence should guide the visit.","source_urls":["https://www.instagram.com/esthetic.joys.embassy/","https://www.gayout.com/europe/armenia/yerevan","https://www.corner.inc/place/pco7bPdjeHEh"],"research_status":"editorial_review_consensus","updated_at":"2026-08-29T00:00:00Z"}'::jsonb),
('Calumet Ethnic Lounge Bar','bar','Calumet''s low tables, wall of flags and long-running live-music rhythm make it a relaxed alternative to formal cocktail rooms. It is a mixed, gay-friendly lounge rather than a queer bar, useful for conversation and a low-pressure first drink close to central community routes.','cushion-strewn Pushkin Street hideaway with live music and an easy mixed crowd','Daily approximately 18:00-03:00; current directories differ slightly, so confirm before a late visit.','https://www.facebook.com/calumet.yerevan/','56/1 Pushkin Street, Kentron, Yerevan 0002, Armenia',40.1841,44.5074,'{"queue_wait":"The cushion seating and live-music evenings favour an earlier arrival if a table matters. Current local directories list late daily service but differ on exact opening time.","best_nights":"Thursday has an established live-music history; otherwise use Calumet as a relaxed conversation stop before a separately verified community event.","crowd_mix":"Students, musicians, travellers, central Yerevan regulars and mixed queer-friendly groups share a low-lit lounge rather than a club floor.","dress_code":"Relaxed everyday clothes fit the floor cushions and informal live sets. There is no published themed-door or formal dress requirement.","staff_inclusivity":"Calumet appears in current queer travel guidance as gay-friendly and is a longstanding licensed mixed bar. It is not LGBTQ+-dedicated and publishes no safeguarding claim; treat it as a socially easier public room, not guaranteed protection.","source_urls":["https://www.gayout.com/europe/armenia/yerevan","https://www.spyur.am/am/companies/calumet-ethnic-lounge-bar/24241/","https://visityerevan.am/restaurants/details/26/en/"],"research_status":"editorial_review_consensus","updated_at":"2026-08-29T00:00:00Z"}'::jsonb),
('The Alexander, a Luxury Collection Hotel, Yerevan','hotel','The Alexander is the high-control landing pad: 114 rooms, concierge depth, an indoor pool and rooftop dining in the historic centre. It suits couples who value privacy, service and an easy walk to central culture more than proximity to a nightlife strip that does not exist.','gold-lit Abovyan luxury with a rooftop restaurant and deeply staffed calm','Hotel open daily; check-in 15:00 and check-out 12:00; minimum check-in age 18.','https://www.marriott.com/en-us/hotels/evnlc-the-alexander-a-luxury-collection-hotel-yerevan/overview/','3/4 Abovyan Street, Yerevan 0001, Armenia',40.1814,44.5158,'{"queue_wait":"Official check-in begins at 15:00 and checkout is noon. The 114-room scale is manageable, but arrange airport arrival and sensitive room details before reaching the desk.","best_nights":"Use the rooftop restaurant or Gabriel''s Bar for a contained first evening, then take a direct ride to a verified event. The hotel has no recurring queer programme.","crowd_mix":"Luxury leisure guests, diplomats, business travellers and affluent local diners create an international, service-heavy environment.","dress_code":"Polished smart casual suits rooftop dining and lounge areas; the pool, hammam and spa use conventional wellness attire.","staff_inclusivity":"Marriott documents concierge service, accessible rooms and international brand operations here, but no Yerevan-specific LGBTQ+ guest protocol. Confirm names, bedding and companion access privately in writing when material.","source_urls":["https://www.marriott.com/en-us/hotels/evnlc-the-alexander-a-luxury-collection-hotel-yerevan/overview/"],"research_status":"editorial_review_consensus","updated_at":"2026-08-29T00:00:00Z"}'::jsonb),
('Tufenkian Historic Yerevan Hotel','hotel','Armenian stone, handwoven textiles and a seasonal pool give this locally rooted boutique hotel more character than an anonymous business stay. Its position between Republic Square and Vernissage makes central days simple while preserving a quieter retreat after an event-led night.','basalt, woven carpets and courtyard quiet beside Vernissage','Hotel open daily; published loyalty terms list check-in 15:00. Confirm checkout and current pool season with the hotel.','https://historic-yerevan.tufenkianheritage.com/','48 Hanrapetutyan Street, Yerevan 0010, Armenia',40.1766,44.5163,'{"queue_wait":"Direct bookings include a transfer offer and reduce arrival ambiguity. Confirm the published 15:00 check-in, checkout time and seasonal-pool availability with the hotel.","best_nights":"This is strongest as a quiet central retreat after Vernissage, Republic Square or a programme elsewhere; Kharpert''s jazz-accented dining can keep the evening on site.","crowd_mix":"Design-conscious travellers, diaspora visitors, cultural tourists and business guests favour the Armenian materials and boutique scale.","dress_code":"Relaxed smart casual fits the carpet-rich public rooms and restaurant; standard pool attire applies during its operating season.","staff_inclusivity":"The hotel publishes direct local contacts and a defined management chain but no LGBTQ+ inclusion protocol. Confirm couple-facing requests and privacy directly rather than inferring practice from boutique positioning.","source_urls":["https://historic-yerevan.tufenkianheritage.com/","https://historic-yerevan.tufenkianheritage.com/contacts/"],"research_status":"editorial_review_consensus","updated_at":"2026-08-29T00:00:00Z"}'::jsonb),
('Holiday Inn Yerevan - Republic Square','hotel','A restored central building, 25-metre indoor pool, sauna and round-the-clock international-hotel rhythm make this the practical option. Republic Square access keeps sightseeing and pickups straightforward, while controlled parking and a staffed lobby reduce late-night friction.','reliable Republic Square base with an indoor-pool reset upstairs','Hotel open daily; check-in 15:00 and check-out 12:00; minimum check-in age 18.','https://www.ihg.com/holidayinn/hotels/us/en/yerevan/evnyv/hoteldetail','2 Amiryan Street, Yerevan 0010, Armenia',40.1783,44.5108,'{"queue_wait":"Check-in starts at 15:00 and checkout is noon. Controlled parking and a staffed front desk simplify arrival; the hotel does not provide an airport shuttle.","best_nights":"Use the lobby bar or 25-metre pool for a low-friction reset, then arrange a direct pickup for any queer event whose entrance has been confirmed.","crowd_mix":"International leisure guests, tour groups, regional business travellers and local meeting attendees share a practical central hotel.","dress_code":"Everyday smart casual fits the lobby and restaurant; pool, sauna, hammam and fitness areas follow standard hotel rules.","staff_inclusivity":"IHG publishes accessible routes, controlled parking and direct contacts for this property, but no local LGBTQ+ service standard. Send privacy, bedding and companion questions to the hotel before arrival.","source_urls":["https://www.ihg.com/holidayinn/hotels/us/en/yerevan/evnyv/hoteldetail","https://www.ihg.com/holidayinn/hotels/us/en/yerevan/evnyv/hoteldetail/directions"],"research_status":"editorial_review_consensus","updated_at":"2026-08-29T00:00:00Z"}'::jsonb)
), upd as (update public.places p set type=s.type,description=s.description,vibe=s.vibe,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,venue_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from s where lower(trim(p.city))='yerevan' and lower(trim(p.name))=lower(s.name) returning p.id)
insert into public.places(name,city,type,description,vibe,hours,link,location,lat,lng,venue_intel,seo_indexable,seo_quality_status) select name,'yerevan',type,description,vibe,hours,link,location,lat,lng,intel,true,'approved' from s where not exists(select 1 from public.places p where lower(trim(p.city))='yerevan' and lower(trim(p.name))=lower(s.name));

with s(name,type,provider_name,contact,booking_link,description,hours,link,location,vibe,tags,source) as (values
('Pink Armenia','other','Pink Human Rights Defender NGO','Hotline +374 33 522533 · office +374 60 377277 · info@pinkarmenia.org','https://pinkarmenia.org/en/','Armenia''s established LGBTQ+ human-rights organisation provides legal assistance, psychological counselling, social-worker support, referrals and a confidential hotline. Contact first; the public listing deliberately avoids exposing a community-office address.','Hotline and appointment-led; contact directly for current service availability.','https://pinkarmenia.org/en/','Yerevan, Armenia — contact-led confidential service','LGBTQ+ legal, psychological and social support',array['legal','health','community']::text[],'Pink Armenia official website and services'),
('Right Side NGO','other','Right Side Human Rights Defender NGO','+374 11 880770 · rightsidengo@gmail.com','https://rightsidengo.com/en','A trans-led organisation serving trans, LGBIQ+ and sex-worker communities through legal help, psychosocial and crisis support, health protection, advocacy and a community safe space. Arrange contact before visiting.','Appointment, programme and hotline-led; contact before visiting.','https://rightsidengo.com/en','Yerevan, Armenia — contact-led safe space','Trans-led legal, health, crisis and safe-space support',array['legal','health','trans','community']::text[],'Right Side NGO official website'),
('New Generation Humanitarian NGO','wellness','New Generation Humanitarian NGO','+374 60 478989 · infongngo@gmail.com','https://ngngo.net/en/public-health/','A community-based health and human-rights organisation offering HIV and sexual-health routes alongside legal support for LGBTQ+ people and key populations. Verify the appropriate service and appointment by phone or email.','Service and appointment-led; contact for current clinic and outreach schedule.','https://ngngo.net/en/public-health/','Yerevan, Armenia — contact for current service point','Community sexual-health, HIV and rights support',array['health','legal','community']::text[],'New Generation official site and ECOM legal-service database')
), upd as (update public.services x set type=s.type,provider_name=s.provider_name,contact=s.contact,booking_link=s.booking_link,description=s.description,hours=s.hours,link=s.link,location=s.location,vibe=s.vibe,vibe_tags=s.tags,source=s.source,"lastChecked"='2026-09-14'::date,verified=true from s where lower(trim(x.city))='yerevan' and lower(trim(x.name))=lower(trim(s.name)) returning x.id)
insert into public.services(name,city,type,provider_name,contact,booking_link,description,hours,link,image_urls,location,lat,lng,price_tier,vibe,vibe_tags,source,"lastChecked",verified) select name,'yerevan',type,provider_name,contact,booking_link,description,hours,link,array[]::text[],location,40.1872,44.5152,'$',vibe,tags,source,'2026-09-14'::date,true from s where not exists(select 1 from public.services x where lower(trim(x.city))='yerevan' and lower(trim(x.name))=lower(trim(s.name)));

insert into public.qa_country_rights_profiles(country,legal_level,rights_level,safety_level,same_sex_relations_status,union_status,legal_gender_recognition_status,anti_discrimination_status,what_this_means,confidence,source_legal_url,source_rights_url,source_safety_url,source_checked_at,needs_manual_review) values
('Armenia','good','risk','risk','legal','no_protection','restricted','limited_or_none','Consensual same-sex relations are legal, but Armenia provides no relationship recognition or comprehensive LGBTQ+-specific anti-discrimination protection. Documented violence, family abuse, extortion and discrimination make practical safety substantially weaker than the legal baseline.','high','https://www.equaldex.com/region/armenia','https://www.hrw.org/world-report/2026/country-chapters/armenia','https://pinkarmenia.org/en/','2026-09-14'::date,false)
on conflict(country) do update set legal_level=excluded.legal_level,rights_level=excluded.rights_level,safety_level=excluded.safety_level,same_sex_relations_status=excluded.same_sex_relations_status,union_status=excluded.union_status,legal_gender_recognition_status=excluded.legal_gender_recognition_status,anti_discrimination_status=excluded.anti_discrimination_status,what_this_means=excluded.what_this_means,confidence=excluded.confidence,source_legal_url=excluded.source_legal_url,source_rights_url=excluded.source_rights_url,source_safety_url=excluded.source_safety_url,source_checked_at=excluded.source_checked_at,needs_manual_review=excluded.needs_manual_review;

insert into public.qa_qari_profiles(destination_key,scope_type,country,city_key,legal_risk,social_risk,digital_risk,risk_floor,confidence,summary,methodology_version,reviewed_by,reviewed_at,is_published) values
('country:armenia','country','Armenia',null,58,84,52,0,'high','Same-sex relations are legal, but Armenia has no couple recognition or comprehensive SOGI protection. Low acceptance and documented violence, extortion, family abuse and discrimination make visibility and dating context-sensitive.','1.0','Queer Atlas editorial review','2026-09-14'::date,true)
on conflict(destination_key) do update set legal_risk=excluded.legal_risk,social_risk=excluded.social_risk,digital_risk=excluded.digital_risk,risk_floor=excluded.risk_floor,confidence=excluded.confidence,summary=excluded.summary,methodology_version=excluded.methodology_version,reviewed_by=excluded.reviewed_by,reviewed_at=excluded.reviewed_at,is_published=excluded.is_published;

delete from public.qa_qari_sources where destination_key='country:armenia';
insert into public.qa_qari_sources(destination_key,axis,source_type,label,url,supports_claim,published_at,checked_at) values
