('country:armenia','social','legal_database','Equaldex · Armenia public opinion','https://www.equaldex.com/region/armenia','Reports 3% saying their area is a good place for gay and lesbian people in 2024.',null,'2026-09-14'::date),
('country:armenia','digital','ngo_report','Human Rights Watch · World Report 2026','https://www.hrw.org/world-report/2026/country-chapters/armenia','Documents violence, extortion, discrimination and law-enforcement abuse affecting LGBT people.',null,'2026-09-14'::date),
